import prettier from 'eslint-config-prettier';
import path from 'node:path';
import js from '@eslint/js';
import jsdoc from 'eslint-plugin-jsdoc';
import svelte from 'eslint-plugin-svelte';
import { defineConfig, includeIgnoreFile } from 'eslint/config';
import globals from 'globals';
import ts from 'typescript-eslint';

const gitignorePath = path.resolve(import.meta.dirname, '.gitignore');

export default defineConfig(
	includeIgnoreFile(gitignorePath),
	{ ignores: ['**/CHANGELOG.md', 'coverage/', '.lighthouseci/', 'playwright-report/'] },
	js.configs.recommended,
	ts.configs.recommended,
	svelte.configs.recommended,
	prettier,
	svelte.configs.prettier,
	{
		languageOptions: { globals: { ...globals.browser, ...globals.node } },
		rules: {
			// typescript-eslint recommends disabling no-undef on TS projects; tsc already catches it.
			'no-undef': 'off'
		}
	},
	{
		files: ['**/*.svelte', '**/*.svelte.ts', '**/*.svelte.js'],
		languageOptions: {
			parserOptions: {
				projectService: true,
				extraFileExtensions: ['.svelte'],
				parser: ts.parser
			}
		}
	},
	{
		files: ['**/*.{js,ts,svelte}'],
		...jsdoc.configs['flat/recommended-typescript-error'],
		rules: {
			...jsdoc.configs['flat/recommended-typescript-error'].rules,
			'jsdoc/require-jsdoc': [
				'error',
				{
					publicOnly: false,
					require: {
						FunctionDeclaration: true,
						MethodDefinition: true,
						ClassDeclaration: true,
						FunctionExpression: false,
						ArrowFunctionExpression: false
					},
					// Named arrow functions need JSDoc; inline callbacks do not.
					contexts: ['VariableDeclarator > ArrowFunctionExpression']
				}
			]
		}
	}
);

import { defineConfig } from 'vitest/config';
import adapter from '@sveltejs/adapter-node';
import { sveltekit } from '@sveltejs/kit/vite';

export default defineConfig({
	plugins: [
		sveltekit({
			compilerOptions: {
				// Runes everywhere except dependencies, which may still ship legacy components.
				runes: ({ filename }) =>
					filename.split(/[/\\]/).includes('node_modules') ? undefined : true
			},
			adapter: adapter()
		})
	],
	test: {
		expect: { requireAssertions: true },
		include: ['src/**/*.{test,spec}.ts', 'scripts/**/*.{test,spec}.ts'],
		environment: 'node',
		coverage: {
			provider: 'v8',
			reporter: ['text', 'lcov'],
			include: ['src/**/*.ts', 'scripts/**/*.ts']
		}
	}
});

import { defineConfig, devices } from '@playwright/test';

export default defineConfig({
	testMatch: '**/*.e2e.ts',
	forbidOnly: !!process.env.CI,
	reporter: process.env.CI ? 'html' : 'list',
	use: { baseURL: 'http://localhost:4173' },
	projects: [{ name: 'mobile', use: { ...devices['Pixel 7'] } }],
	webServer: { command: 'pnpm build && pnpm preview', port: 4173 }
});

export default {
	extends: ['@commitlint/config-conventional'],
	plugins: ['commitlint-plugin-rai'],
	rules: {
		'rai-footer-exists': [2, 'always'],
		'rai-signed-off-by': [2, 'always']
	}
};

